CREATE TABLE vocabulary_words (
    id BIGSERIAL PRIMARY KEY,
    unit_number INT NOT NULL CHECK (unit_number > 0),
    cluster VARCHAR(80) NOT NULL,
    word VARCHAR(80) NOT NULL,
    part_of_speech VARCHAR(24) NOT NULL,
    definition TEXT NOT NULL,
    example_sentence TEXT NOT NULL,
    collocation VARCHAR(180) NOT NULL,
    noun_form VARCHAR(80),
    adjective_form VARCHAR(80),
    darija_gloss VARCHAR(180),
    CONSTRAINT uq_vocabulary_unit_word UNIQUE (unit_number, word)
);

CREATE INDEX idx_vocabulary_words_unit_cluster ON vocabulary_words(unit_number, cluster);

CREATE TABLE user_vocabulary_progress (
    id BIGSERIAL PRIMARY KEY,
    user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    vocabulary_word_id BIGINT NOT NULL REFERENCES vocabulary_words(id) ON DELETE CASCADE,
    status VARCHAR(16) NOT NULL DEFAULT 'NEW' CHECK (status IN ('NEW', 'LEARNING', 'KNOWN', 'REVIEW')),
    marked_known BOOLEAN NOT NULL DEFAULT FALSE,
    last_seen_at TIMESTAMPTZ,
    next_review_at TIMESTAMPTZ,
    review_count INT NOT NULL DEFAULT 0 CHECK (review_count >= 0),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT uq_user_vocabulary_progress UNIQUE (user_id, vocabulary_word_id)
);
CREATE INDEX idx_user_vocabulary_review_queue ON user_vocabulary_progress(user_id, next_review_at);

